// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the encoded maintenance value used during initialize
    // We pass a uint256 which will be converted to UFixed18 via UFixed18.wrap(a * 1e18) by the product initialize path.
    // Keep domain wide but avoid overflow when encoding into UFixed18 via helper conversion in calldata assembly
    function testFuzz_property(uint256 maintenanceRaw) public {
        // keep maintenanceRaw in a wide but reasonable range to represent UFixed18 values
        maintenanceRaw = bound(maintenanceRaw, 0, type(uint128).max);

        // Prepare minimal ProductInfo to call initialize on C.
        // We need to construct all fields; many are unused for this test but must be provided.
        // Build a calldata struct by encoding then delegatecall into initialize.

        // We'll craft memory for ProductInfo and call initialize via low-level call on c.
        // Types: (string name, string symbol, PayoffDefinition payoffDefinition, IOracleProvider oracle,
        // UFixed18 maintenance, UFixed18 fundingFee, UFixed18 makerFee, UFixed18 takerFee,
        // UFixed18 positionFee, UFixed18 makerLimit, JumpRateUtilizationCurve utilizationCurve)

        // For simplicity use empty strings and zeroed complex structs; oracle can be address(1) but must be a contract when used later
        // However initialize only stores values and checks Address.isContract on controller in __UControllerProvider__initialize,
        // which uses msg.sender as controller (we call initialize as test runner so msg.sender will be this test contract) — the code expects msg.sender to be IController and Address.isContract(msg.sender) must be true.
        // To satisfy that, we deploy a minimal fake controller contract.

        ControllerFake controller = new ControllerFake();
        // Prank msg.sender to be the controller when calling initialize
        vm.prank(address(controller));

        // Build minimal structs in memory and call initialize on c
        // Use abi.encode to create the ProductInfo argument and call c.initialize
        bytes memory name = abi.encodePacked("n");
        bytes memory symbol = abi.encodePacked("s");

        // payoffDefinition: PayoffDefinition is (PayoffType, PayoffDirection, bytes30) stored as 32+32+32
        // We'll pass zeros
        bytes30 empty30 = bytes30(0);

        // oracle address: use address(2) as placeholder; UPayoffProvider may call _updateOracle which checks isContract(newOracle) in _updateOracle called during __UPayoffProvider__initialize
        // _updateOracle is called with address(oracle_) and checks Address.isContract(newOracle) -> must be contract. Deploy a minimal OracleFake.
        OracleFake oracle = new OracleFake();

        // Build JumpRateUtilizationCurve zeroed (4 fields): use zeros

        // Encode UFixed18 values: these are uint256. We set maintenance to maintenanceRaw * 1e18 to match UFixed18.from(uint256)
        uint256 BASE = 1e18;
        uint256 maintenanceEncoded = maintenanceRaw * BASE;
        uint256 zeroUFixed = 0;

        // Pack ProductInfo via abi.encode with matching types
        bytes memory productInfo = abi.encode(
            string(name),
            string(symbol),
            // PayoffDefinition: encode as (uint8,uint8,bytes30) but solidity will accept tuple of (uint8,uint8,bytes30) as struct
            // We encode fields directly
            // To match calldata for initialize(ProductInfo calldata), rely on abi.encode matching layout
            // We'll encode a tuple: (uint8,uint8,bytes30)
            uint8(0), uint8(0), empty30,
            address(oracle),
            maintenanceEncoded,
            zeroUFixed,
            zeroUFixed,
            zeroUFixed,
            zeroUFixed,
            zeroUFixed,
            // JumpRateUtilizationCurve: (PackedFixed18 minRate, PackedFixed18 maxRate, PackedFixed18 targetRate, PackedUFixed18 targetUtilization)
            int128(0), int128(0), int128(0), uint128(0)
        );

        // Call initialize
        (bool ok, ) = address(c).call(abi.encodeWithSignature("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))", name, symbol, abi.encode(uint8(0), uint8(0), empty30), address(oracle), maintenanceEncoded, 0, 0, 0, 0, 0, int128(0), int128(0), int128(0), uint128(0)));
        // The above complex direct signature can be brittle; instead call via a small wrapper on controller fake which calls initialize as controller
        // Use controller to forward a proper call that sets msg.sender as controller inside initialize
        // We already deployed controller; call its forwardInitialize
        vm.prank(address(controller));
        controller.forwardInitialize(address(c), name, symbol, empty30, address(oracle), maintenanceEncoded);

        // Now call maintenance() and compare to stored maintenanceEncoded interpreted as UFixed18 (uint256)
        // The property: c.maintenance() must equal UFixed18.wrap(maintenanceEncoded) i.e. the same numeric value
        // We fetch the return value and assert equality.
        uint256 reported = uint256(c.maintenance());

        // The one assertion: reported equals maintenanceEncoded
        assertTrue(reported == maintenanceEncoded);
    }
}

// Minimal fake controller that is a contract (so Address.isContract passes) and can forward initialize call while being msg.sender in that call
contract ControllerFake {
    function forwardInitialize(address product, bytes memory name, bytes memory symbol, bytes30 empty30, address oracle, uint256 maintenanceEncoded) public {
        // build ProductInfo struct and call initialize on product with msg.sender == this contract
        // Construct tuple inline matching C.initialize signature
        // Use abi.encodeWithSignature with explicit types to avoid mismatch
        (bool ok, ) = product.call(abi.encodeWithSignature(
            "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))",
            string(name), string(symbol), uint8(0), uint8(0), empty30, oracle,
            maintenanceEncoded, 0, 0, 0, 0, 0,
            int128(0), int128(0), int128(0), uint128(0)
        ));
        require(ok, "init failed");
    }
}

