// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the maintenance value (as a raw uint256 representing UFixed18 value / 1e18) and an address
    function testFuzz_property(uint256 maintenanceRaw, address account) public {
        // keep maintenance in a wide admissible range but not constrained to equal ONE
        // interpret maintenanceRaw as the unwrapped UFixed18 value (i.e., stored units, not scaled here)
        // bound to avoid overflow in UFixed18.wrap when using extremely large raw (but keep wide)
        maintenanceRaw = bound(maintenanceRaw, 0, type(uint256).max / 2);

        // Build a ProductInfo with maintenance = UFixed18.wrap(maintenanceRaw)
        // We cannot construct UFixed18 type directly here, but C.initialize expects ProductInfo calldata.
        // To avoid importing ProductInfo type (it's in C), craft a minimal bytes encoding of the struct
        // However simpler: call initialize with msg.sender as controller (per contract's expectation),
        // but initialize requires a ProductInfo struct; forge can encode with abi.encode.

        // Prepare fields for ProductInfo in the same order as contract expects:
        // string name; string symbol; PayoffDefinition payoffDefinition; IOracleProvider oracle;
        // UFixed18 maintenance; UFixed18 fundingFee; UFixed18 makerFee; UFixed18 takerFee;
        // UFixed18 positionFee; UFixed18 makerLimit; JumpRateUtilizationCurve utilizationCurve;
        // We'll pass zero/empty values for unused items and set maintenance to maintenanceRaw.

        // Create minimal dummy bytes for complex types (their exact internal layout isn't checked by initialize beyond storing maintenance)
        bytes memory name = abi.encode("n");
        bytes memory symbol = abi.encode("s");
        bytes memory payoffDefinition = abi.encode(bytes30(0));
        address oracle = address(0);
        uint256 maintenanceWrapped = maintenanceRaw; // treat as already scaled units
        uint256 fundingFee = 0;
        uint256 makerFee = 0;
        uint256 takerFee = 0;
        uint256 positionFee = 0;
        uint256 makerLimit = 0;
        // for utilization curve, pass zeros for packed fields
        bytes memory utilizationCurve = abi.encode(uint128(0), int128(0), int128(0), uint128(0));

        // Construct ProductInfo tuple ABI encoding matching the struct layout; use tuple encoding
        bytes memory productInfoEncoded = abi.encode(
            name,
            symbol,
            payoffDefinition,
            oracle,
            maintenanceWrapped,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            utilizationCurve
        );

        // Call initialize via low-level call encoding the expected function selector and ProductInfo
        // Function signature: initialize(ProductInfo)
        bytes4 sig = bytes4(keccak256("initialize((string,string,bytes30,address,uint256,uint256,uint256,uint256,uint256,uint256,bytes))"));

        // Since encoding exact nested types is delicate, and the contract's initialize uses the concrete ProductInfo type from C,
        // we instead perform a direct low-level call to set the maintenance storage by calling __UParamProvider__initialize
        // but that is internal. Therefore, to satisfy constraints we use the public maintenance() view which reads stored value.
        // To set the stored maintenance without calling initialize, we cannot access private storage.
        // Instead, exploit that UParamProvider._updateMaintenance emits an event and stores value only during initialize or updateMaintenance (external onlyProductOwner).
        // We cannot call updateMaintenance (requires onlyProductOwner). So we will treat the contract as uninitialized: in reference, maintenance() reads storage default zero.
        // The mutant returns ONE always. Thus universal property: for ANY account and ANY maintenanceRaw where maintenanceStored == UFixed18.ZERO, maintenance(account) == UFixed18.ZERO.
        // So we choose to assert that when contract is uninitialized, maintenance(account) == UFixed18.ZERO. The mutant returns ONE and will fail for many fuzz inputs.

        // Call maintenance(account) and check it equals zero (uninitialized storage default)
        // Wrap call in try/catch to ensure we observe non-revert behaviour
        bool ok;
        try c.maintenance(account) returns (uint256 v) {
            // UFixed18 is a user-defined type; at ABI layer it is uint256. We get v as the raw unwrapped value.
            ok = (v == 0);
        } catch {
            // if maintenance reverts, that's a violation, but reference shouldn't revert; set ok = false
            ok = false;
        }

        // Single assertion: reference contract (uninitialized) always returns zero maintenance for any account; mutant returning ONE breaks this for many inputs
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // fuzz the maintenance value (as a raw uint256 representing the unscaled integer part)
    function testFuzz_property(uint256 maintenanceWhole) public {
        // keep the fuzzed domain wide but bounded to avoid overflow when scaled by 1e18
        maintenanceWhole = bound(maintenanceWhole, 0, type(uint128).max);

        // construct a minimal ProductInfo to initialize c; many fields are unused by maintenance getter
        C.ProductInfo memory info;
        info.name = "p";
        info.symbol = "s";
        // payoffDefinition and oracle are only used in initializer checks; pass zero values that still satisfy
        // For simplicity we set oracle to address(this) cast to IOracleProvider; initializer checks Address.isContract
        // so we deploy a tiny helper oracle contract below and use it.
        OracleHelper oracle = new OracleHelper();
        info.oracle = IOracleProvider(address(oracle));
        // payoffDefinition: use a simple default valid PayoffDefinition via PayoffDefHelper
        PayoffDefHelper payoff = new PayoffDefHelper();
        info.payoffDefinition = payoff.make();

        // set maintenance as UFixed18.from(maintenanceWhole)
        info.maintenance = UFixed18.wrap(maintenanceWhole * 1e18);
        info.fundingFee = UFixed18Lib.ZERO;
        info.makerFee = UFixed18Lib.ZERO;
        info.takerFee = UFixed18Lib.ZERO;
        info.positionFee = UFixed18Lib.ZERO;
        info.makerLimit = UFixed18Lib.MAX;
        // utilization curve default (zeros)
        JumpRateUtilizationCurve memory curve;
        curve.minRate = PackedFixed18.wrap(0);
        curve.maxRate = PackedFixed18.wrap(0);
        curve.targetRate = PackedFixed18.wrap(0);
        curve.targetUtilization = PackedUFixed18.wrap(0);
        info.utilizationCurve = curve;

        // initialize c by simulating that msg.sender is a controller contract (owner expectations inside initialize)
        // The initializer expects msg.sender to be a contract address (Address.isContract) and then uses it as controller
        ControllerHelper controller = new ControllerHelper();
        vm.prank(address(controller));
        c.initialize(info);

        // call maintenance; it should return exactly the stored value we initialized
        UFixed18 returned = c.maintenance(address(0));

        // assert the reference returns the stored maintenance value (this will fail on the mutant that returns ONE
        // whenever our initialized maintenanceWhole != 1)
        assertTrue(UFixed18.unwrap(returned) == maintenanceWhole * 1e18);
    }
}

// Minimal helpers used to satisfy initializer expectations

interface IOracleProvider {
    struct OracleVersion { uint256 version; uint256 timestamp; Fixed18 price; }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
}

// Minimal types and libraries declarations needed for the helpers (lightweight stubs matching names used in C)

type Fixed18 is int256;
type UFixed18 is uint256;
type PackedFixed18 is int128;
type PackedUFixed18 is uint128;

library UFixed18Lib {
    UFixed18 internal constant ZERO = UFixed18.wrap(0);
    UFixed18 internal constant ONE = UFixed18.wrap(1e18);
    UFixed18 internal constant MAX = UFixed18.wrap(type(uint256).max);
}

library Fixed18Lib {
    function from(int256 s, UFixed18 m) internal pure returns (Fixed18) { return Fixed18.wrap(0); }
}

contract OracleHelper {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        IOracleProvider.OracleVersion memory v;
        v.version = 1;
        v.timestamp = block.timestamp;
        v.price = Fixed18.wrap(0);
        return v;
    }
    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) { return sync(); }
    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) { return sync(); }
}

// Very small PayoffDefinition stub and helper to satisfy initializer checks
struct PayoffDefinition { uint8 _dummy; }

contract PayoffDefHelper {
    function make() external pure returns (PayoffDefinition memory) {
        PayoffDefinition memory p;
        p._dummy = 1;
        return p;
    }
}

// Minimal Controller helper: must be a contract (isContract true) and provide functions used by C.initialize path
contract ControllerHelper {
    function collateral() external pure returns (address) { return address(0); }
    function incentivizer() external pure returns (address) { return address(0); }
    function isProduct(address) external pure returns (bool) { return false; }
    function owner() external pure returns (address) { return address(this); }
    function owner(uint256) external pure returns (address) { return address(this); }
    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }
}

