// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the stored maintenance value (as uint256) and an arbitrary account address
    function testFuzz_property(uint256 maintenanceRaw, address account) public {
        // Keep maintenance in a reasonable UFixed18 range: multiply into 18-decimal fixed format
        // bound to [0, 1e36] to allow values both equal and not equal to UFixed18Lib.ONE (1e18)
        uint256 bounded = bound(maintenanceRaw, 0, 1e36);

        // Build a ProductInfo via calldata-like struct requires constructing fields; but initialize only reads many fields.
        // We'll craft minimal ProductInfo by ABI-encoding and calling initialize via low-level call is not allowed.
        // Instead, we rely on the fact that initialize expects ProductInfo calldata; we must construct it directly.
        // Define local types matching ProductInfo in C by creating memory struct via tuple arguments.
        C.ProductInfo memory info;

        // Set name/symbol arbitrary
        info.name = "P";
        info.symbol = "S";

        // payoffDefinition and oracle can be zero values (addresses zero) because __UPayoffProvider__initialize will call _updateOracle which requires a contract; to avoid revert, we will set msg.sender as controller when calling initialize as required by setUp.
        // The initialize function expects caller to be controller address; setUp created c with no controller; but __UControllerProvider__initialize expects IController(msg.sender)
        // Therefore we must call initialize as if msg.sender is an IController contract; forge test runs as this test contract, which is not a contract implementing IController, but __UControllerProvider__initialize only checks Address.isContract(address(controller_)) which will be false for EOA. However C.initialize uses initializer modifier which allows onlyInitializer and calls __UControllerProvider__initialize(IController(msg.sender)); Since msg.sender in initialize will be this test contract, and this contract is a contract, Address.isContract will return true. So pass.

        // Set oracle to address(0) placeholder; payoffDefinition zeroed
        info.oracle = IOracleProvider(address(0));
        info.payoffDefinition = C.PayoffDefinition({payoffType: C.PayoffDefinitionLib.PayoffType(0), payoffDirection: C.PayoffDefinitionLib.PayoffDirection(0), data: bytes30(0)});

        // Set maintenance using UFixed18 encoding: UFixed18.wrap(bounded * 1e18)
        // But we cannot call UFixed18.wrap from here; instead pass the UFixed18 via its abi-compatible uint256 value
        // The ProductInfo struct field is type UFixed18; we can set it by casting the uint256
        info.maintenance = UFixed18.wrap(bounded);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve({minRate: PackedFixed18.wrap(0), maxRate: PackedFixed18.wrap(0), targetRate: PackedFixed18.wrap(0), targetUtilization: PackedUFixed18.wrap(0)});

        // Now call initialize as this contract (which is a deployed contract and thus Address.isContract will be true)
        // Must cast to IController for msg.sender check inside initialize; but initialize simply calls __UControllerProvider__initialize(IController(msg.sender)) which uses Address.isContract on msg.sender; our test contract is a contract so it's OK.
        c.initialize(info);

        // Call maintenance for the fuzzed account and observe returned UFixed18 via try/catch to be robust
        bool ok;
        try c.maintenance(account) returns (UFixed18 val) {
            ok = true;
            // Now assert that the returned value equals the stored maintenance we initialized.
            // We must read stored maintenance via c.maintenance() again — but single assertion required: so combine equality into one assertTrue below by computing equality now.
            // Pack equality into ok flag by comparing raw unwraps
            uint256 returned = UFixed18.unwrap(val);
            uint256 expected = UFixed18.unwrap(c.maintenance()); // this reads the same as returned for reference; but to satisfy single assertion reading c, we'll set ok to (returned == expected)
            ok = (returned == expected);
        } catch {
            ok = false;
        }

        // Single assertion: for the correct contract, maintenance(account) should equal stored maintenance for all inputs; the mutant returning ONE will break for some inputs (when stored maintenance != ONE)
        assertTrue(ok);
    }
}

