// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, IProduct, IOracleProvider, PayoffDefinition, JumpRateUtilizationCurve, UFixed18, UFixed18Lib} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: maintenanceRaw is any uint256 that will be converted to UFixed18 via wrap-like semantics
    function testFuzz_property(uint256 maintenanceRaw) public {
        // keep maintenance within a wide admissible range (0 .. 1e27) to avoid overflowing packed representations
        maintenanceRaw = bound(maintenanceRaw, 0, 1e27);

        // Build a minimal ProductInfo to initialize C. Many fields can be zero/empty; we only care about maintenance.
        IProduct.ProductInfo memory info;
        info.name = "P";
        info.symbol = "S";

        // payoffDefinition: use empty/default bytes; C only validates .valid() in reference code, but to avoid dependency
        // on complex libraries we set a zeroed payoffDefinition that the real C accepts in the test environment.
        // We'll create an innocuous PayoffDefinition with payoffType=0,payoffDirection=0,data=0.
        PayoffDefinition memory pd;
        pd = PayoffDefinition({payoffType: PayoffDefinitionLib.PayoffType(0), payoffDirection: PayoffDefinitionLib.PayoffDirection(0), data: bytes30(0)});
        info.payoffDefinition = pd;

        // oracle: use address(this) cast to IOracleProvider only for initializer; the reference C's __UPayoffProvider__initialize
        // calls _updateOracle which requires Address.isContract(newOracle) -> our deployed c is a contract, but passing address(this)
        // (the test contract) is also a contract, so it's fine. Create a minimal oracle mock via a tiny helper below would be heavier;
        // to keep minimal, pass IOracleProvider(address(this)). The test won't call oracle methods.
        info.oracle = IOracleProvider(address(this));

        // Set maintenance using UFixed18.wrap-like semantics: multiply by 1e18
        UFixed18 maintenance = UFixed18Lib.from(maintenanceRaw);
        info.maintenance = maintenance;

        // set other numeric params to zero
        info.fundingFee = UFixed18Lib.ZERO;
        info.makerFee = UFixed18Lib.ZERO;
        info.takerFee = UFixed18Lib.ZERO;
        info.positionFee = UFixed18Lib.ZERO;
        info.makerLimit = UFixed18Lib.ZERO;

        // utilizationCurve: zeroed struct
        JumpRateUtilizationCurve memory curve;
        curve.minRate = PackedFixed18.wrap(0);
        curve.maxRate = PackedFixed18.wrap(0);
        curve.targetRate = PackedFixed18.wrap(0);
        curve.targetUtilization = PackedUFixed18.wrap(0);
        info.utilizationCurve = curve;

        // Initialize contract under test
        c.initialize(info);

        // pick an arbitrary account (fuzzed not allowed here per constraints) — we must let property quantify over account as well,
        // but fuzz requires at least one param; maintenanceRaw is fuzzed and suffices to find difference because maintenance() ignores account.
        address someAccount = address(0x123);

        // Query maintenance via try/catch to be robust to any unexpected revert; we expect reference to return stored maintenance
        bool ok;
        UFixed18 returned;
        try c.maintenance(someAccount) returns (UFixed18 v) {
            ok = true;
            returned = v;
        } catch {
            ok = false;
            returned = UFixed18Lib.ZERO;
        }

        // The general rule: reference returns the stored maintenance value and thus the call should succeed (ok==true)
        // and the returned value equals the initialized maintenance. The mutant that hardcodes ONE will violate equality when
        // maintenance != ONE. We assert this equality (single assertTrue) — it holds for reference for all maintenanceRaw and
        // is falsified by the mutant for some maintenanceRaw values.
        assertTrue(ok && (returned.eq(maintenance)));
    }
}

// Minimal stubs used above: because we imported types from C_under_test.sol, we need tiny helpers for types referenced in the test
// The following are minimal re-declarations to satisfy the compiler for the test file. They mirror the originals enough for the test.

enum PayoffType { ZERO }
enum PayoffDirection { ZERO }

library PayoffDefinitionLib {
    enum PayoffType { ZERO }
    enum PayoffDirection { ZERO }
}

type PackedFixed18 is int128;
using PackedFixed18Lib for PackedFixed18 global;
library PackedFixed18Lib { function wrap(int128 v) internal pure returns (PackedFixed18) { return PackedFixed18.wrap(v); } }

type PackedUFixed18 is uint128;
using PackedUFixed18Lib for PackedUFixed18 global;
library PackedUFixed18Lib { function wrap(uint128 v) internal pure returns (PackedUFixed18) { return PackedUFixed18.wrap(v); } }

// Minimal wrappers to allow compilation of the test that references PayoffDefinition and JumpRateUtilizationCurve
struct PayoffDefinition { PayoffType payoffType; PayoffDirection payoffDirection; bytes30 data; }
struct JumpRateUtilizationCurve { PackedFixed18 minRate; PackedFixed18 maxRate; PackedFixed18 targetRate; PackedUFixed18 targetUtilization; }

// Minimal UFixed18 type and lib (mirror of contract's types used in test assertions)
type UFixed18 is uint256;

library UFixed18Lib {
    UFixed18 internal constant ZERO = UFixed18.wrap(0);
    UFixed18 internal constant ONE = UFixed18.wrap(1e18);
    function from(uint256 a) internal pure returns (UFixed18) { return UFixed18.wrap(a * 1e18); }
    function eq(UFixed18 a, UFixed18 b) internal pure returns (bool) { return UFixed18.unwrap(a) == UFixed18.unwrap(b); }
}

// Note: The above test relies on imported C to compile; if the project already exposes the types, some of these
