// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the newMaintenance value that should be applied
    function testFuzz_property(uint256 newMaintenanceRaw) public {
        // keep the fuzzed value within a wide admissible domain
        // interpret as UFixed18 by wrapping (the contract uses UFixed18 as uint256 scaled by 1e18)
        // we allow any uint256; no tight assumption so fuzzer can find differing cases

        // call updateMaintenance from the product owner: in C.initialize, controller() is msg.sender
        // but here we can call updateMaintenance directly because onlyProductOwner modifier checks controller().owner(...)
        // To avoid complex controller wiring, we will simply call updateMaintenance via low-level call as an external caller
        // However the modifier onlyProductOwner will likely revert in normal environment; instead we only need to observe
        // the property on the storage after a successful call. To get a successful call, we simulate environment by
        // deploying a mock controller and initializing C via its initialize. But the test harness requires using new C() only
        // for deployment; we can still interact with C's public functions—however many modifiers require controller setup.
        // To bypass initialization requirements and still invoke updateMaintenance, we'll directly call updateMaintenance expecting it to revert
        // when not authorized; but the property we assert must read maintenance after a successful authorized update.
        // Therefore we will perform the correct initialization flow: we deploy a minimal MockController that satisfies
        // the checks and then call initialize on C with proper productInfo via a prank from the mock controller.

        // Deploy a minimal mock controller that implements the small subset needed
        MockController controller = new MockController();

        // Prepare a ProductInfo in calldata by creating a memory struct compatible with C.ProductInfo
        // Since ProductInfo is declared in the imported contract, we must recreate it via low-level ABI encode and call initialize.
