    function testFuzz_property(uint256 newFundingFeePacked) public {
        // 1) make ownerAddr be the controller owner by deploying a very small Controller that reports owner==ownerAddr
        // but C expects controller() to be msg.sender at initialize time; we must initialize C via calling initialize with msg.sender == controller
        // Deploy a tiny Controller that returns itself as collateral and owner
        SimpleController controller = new SimpleController();

        // set controller's collateral to our malicious collateral
        controller.setCollateral(address(mal));
        // make ownerAddr be the owner for coordinator 0
        controller.setOwner(ownerAddr);

        // initialize product: we must call C.initialize with msg.sender == controller
        // prepare a minimal ProductInfo struct: C expects a lot of types; construct via abi.encode/assembly via helper
        // But simpler: craft calldata by calling C.initialize via vm.prank(controller)

        // Build a minimal ProductInfo in memory using the types; create through a helper contract that knows the types
        ProductInfoBuilder builder = new ProductInfoBuilder();
        bytes memory productInfoCalldata = builder.build(address(0), "n", "s");

        vm.prank(address(controller));
        // low-level call to initialize with encoded ProductInfo
        (bool ok, ) = address(c).call(productInfoCalldata);
        require(ok, "initialize failed");

        // now make controller() of c return our controller: we must trick c into thinking controller() == controller
        // C stores controller in its UControllerProvider during __UControllerProvider__initialize which used msg.sender (controller)
        // so controller() already returns our controller because we called initialize from controller address.

        // Now we want to call updateFundingFee as the product owner: ownerAddr must be msg.sender
        // The reference contract has settleProduct modifier on updateFundingFee, so it will call settle which will call controller.collateral().settleProduct
        // Our malicious collateral reverts on settleProduct; so reference should revert. The mutant without settle will not revert.

        // Derive a UFixed18 value: keep wide domain but restrict to <= UFixed18Lib.ONE (1e18) to satisfy param validation in _updateFundingFee
        uint256 maxOne = 1e18;
        uint256 packed = newFundingFeePacked % (maxOne + 1);

        // We need to craft UFixed18 representation expected by the contract (it's a wrapper over uint256 scaled by 1e18).
        // The contract's external signature is updateFundingFee(UFixed18), and solidity ABI will encode a uint256.
        // We call via high-level call to c.updateFundingFee using vm.prank(ownerAddr)

        vm.prank(ownerAddr);
        bool success;
